  static long solve(int[] a) {
Deque<Integer> stack=new ArrayDeque<>();long best=0;for(int i=0;i<=a.length;i++){int height=i==a.length?0:a[i];while(!stack.isEmpty()&&a[stack.peek()]>height){int h=a[stack.pop()],left=stack.isEmpty()?-1:stack.peek();best=Math.max(best,(long)h*(i-left-1));emit("Finalize a rectangle at its first smaller right boundary","height",h,"boundaries",new int[]{left,i},"best",best);}if(i<a.length)stack.push(i);}return best;
